import assert from 'node:assert/strict';
import {writeFileSync,readFileSync,mkdirSync,readdirSync,lstatSync,mkdtempSync,rmSync} from 'node:fs';
import {join,resolve,delimiter} from 'node:path';import {tmpdir} from 'node:os';import {spawnSync}from'node:child_process';import {createHash}from'node:crypto';
import {withProject,traceMd,ledgerRow,requirement,reportJson}from'./project.mjs';
const repo=process.cwd(),cli=join(repo,'packages/cli/dist/cli.js'),scratch=mkdtempSync(join(tmpdir(),'loomake-cli-scale-'));
const sha=value=>createHash('sha256').update(value).digest('hex');
const snapshot=folder=>Object.fromEntries(readdirSync(folder,{withFileTypes:true}).flatMap(e=>{const p=join(folder,e.name);assert(!e.isSymbolicLink());return e.isDirectory()?Object.entries(snapshot(p)).map(([f,v])=>[join(e.name,f),v]):[[e.name,{bytes:lstatSync(p).size,sha256:sha(readFileSync(p))}]]}));
const rows=[];const preload=join(scratch,'metrics.cjs');writeFileSync(preload,"process.on('exit',()=>require('node:fs').writeFileSync(process.env.LOOMAKE_PROFILE_OUTPUT,JSON.stringify({peakCliRssBytes:process.resourceUsage().maxRSS*1024,cpuUserMicros:process.resourceUsage().userCPU,cpuSystemMicros:process.resourceUsage().systemCPU})));\n");
try{
 for(const [requirements,fileCount]of [[10,20],[100,200],[500,1000]]){
 const ids=Array.from({length:requirements},(_,i)=>`REQ-${String(i+1).padStart(3,'0')}`);
 const spec=['## ADDED Requirements','',...ids.map(id=>requirement(`振る舞い ${id}`,{source:`Source: ${id}`}))].join('\n');
 withProject({trace:traceMd({ledger:ids.map(id=>ledgerRow(id))}),spec,config:{openspecValidate:true,commands:{}}},root=>{
 mkdirSync(join(root,'tests'));mkdirSync(join(root,'.loomake'));const cases={};for(let i=0;i<fileCount;i++){const file=`tests/t${i}.test.ts`;cases[file]=[[`[${ids[i%ids.length]}] case ${i}`,'passed']];writeFileSync(join(root,file),`it('[${ids[i%ids.length]}] case ${i}',()=>{});\n`);}
 writeFileSync(join(root,'.loomake/test-report.json'),reportJson(root,cases));const before=snapshot(root);
 for(let attempt=1;attempt<=3;attempt++){
 const metrics=join(scratch,`m-${requirements}-${attempt}.json`);const started=performance.now();const ran=spawnSync(process.execPath,['--require',preload,cli,'verify','--change','c1','--done','--skip-commands','--json'],{cwd:root,env:{...process.env,PATH:join(repo,'node_modules/.bin')+delimiter+process.env.PATH,LOOMAKE_PROFILE_OUTPUT:metrics},encoding:'utf8',timeout:15000,maxBuffer:8*1024*1024});const wallMs=performance.now()-started;
 assert.equal(ran.error,undefined);assert.equal(ran.status,0,ran.stdout+ran.stderr);const value=JSON.parse(ran.stdout);assert.equal(value.ok,true);assert.equal(Object.keys(value.coverage).length,requirements);assert(value.results.some(r=>r.check==='openspec validate'&&r.status==='pass'));assert(value.results.some(r=>r.check==='品質コマンド'&&r.status==='skip'));
 const after=snapshot(root);assert.deepEqual(after,before);const resource=JSON.parse(readFileSync(metrics,'utf8'));rows.push({requirements,files:fileCount,attempt,wallMs,stdoutBytes:Buffer.byteLength(ran.stdout),stderrBytes:Buffer.byteLength(ran.stderr),logicalFixtureBytes:Object.values(before).reduce((a,v)=>a+v.bytes,0),logicalBytesAdded:0,inputAndReportUnchanged:true,...resource,withinExistingThreeSecondTimeLimit:wallMs<3000});
 }
 });
 }
 const files=['packages/cli/dist/cli.js','packages/cli/dist/main.js','packages/kit/dist/verify/run.js','packages/kit/dist/input.js','packages/core/dist/index.js','packages/runner/src/run/decision-policy.ts','packages/cli/test/cli.test.ts'];
 const result={sourceCommit:'55ed8e3',node:process.version,platform:process.platform,arch:process.arch,scope:'Actual compiled CLI process startup through verify completion, with real local OpenSpec validation and --skip-commands; seeded synthetic test reports, no test command run',limits:['Peak RSS is the CLI process only and excludes OpenSpec child RSS.','Logical fixture bytes exclude filesystem allocation and tool caches outside the fixture.','Three runs per scale on one host; fixtures were prepared before timing, so filesystem cache can be warm.','No RSS or disk SLO is inferred from the measurements.'],inputs:Object.fromEntries(files.map(f=>[f,sha(readFileSync(join(repo,f)))])),probeSha256:sha(readFileSync(new URL(import.meta.url))),rows};writeFileSync(resolve('.loomake/quality/edge-probes/cli-scale-results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(rows.map(r=>({requirements:r.requirements,attempt:r.attempt,ms:Math.round(r.wallMs),rssMiB:Math.round(r.peakCliRssBytes/1024/1024),outputBytes:r.stdoutBytes}))));
}catch(error){console.error(error);process.exitCode=1;}finally{rmSync(scratch,{recursive:true,force:true});}
